/**
 * Organization activity feed; requires `activity:read` and the `activity_feed`
 * flag.
 *
 * Owner D. Two gates that fail differently on purpose: a missing permission is
 * a 404 (the page should not exist for you), a disabled flag is an explanation
 * (the page exists, your plan does not include it).
 *
 * Must call (do not reimplement): can, isEnabled
 */

import { notFound } from "next/navigation";
import type { Metadata } from "next";
import { ActivityFeed } from "@/components/domain/activity/activity-feed";
import { EmptyState } from "@/components/ui/empty-state";
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import { groupByDay, listActivity } from "@/server/services/activity-service";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { listMembers } from "@/server/services/member-service";
import { searchParamsPaginationSchema } from "@/schemas/pagination";
import type { User } from "@/types/member";
import { loadTenantContext } from "../_lib/tenant-context";

type PageParams = { orgSlug: string };

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Activity",
};

const MEMBER_LOOKUP_LIMIT = 100;

export default async function Page(props: {
  params: Promise<PageParams>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // Next.js 16: params and searchParams are Promises and MUST be awaited.
  const { orgSlug } = await props.params;
  const search = await props.searchParams;

  const { org, actor } = await loadTenantContext(orgSlug);

  if (!can(actor, "activity:read", { kind: "activity", orgId: org.id })) {
    notFound();
  }

  if (!isEnabled("activity_feed", buildFlagContext(actor, org))) {
    return (
      <EmptyState
        title="The activity feed is not part of this plan"
        description="Upgrade in Settings → Billing to keep an audit trail of every change."
      />
    );
  }

  const pagination = searchParamsPaginationSchema.parse(search);

  const [page, members] = await Promise.all([
    listActivity(actor, {
      orgId: org.id,
      limit: pagination.perPage,
      cursor: pagination.cursor ?? null,
    }),
    listMembers(actor, { orgId: org.id, limit: MEMBER_LOOKUP_LIMIT }),
  ]);

  const actors: Record<string, User> = {};
  for (const member of members.items) {
    actors[member.userId] = member.user;
  }

  return (
    <div className="space-y-8">
      <header>
        <h1 className="text-2xl font-semibold tracking-tight">Activity</h1>
        <p className="mt-1 text-sm text-slate-600">
          Every change made in {org.name}, newest first.
        </p>
      </header>

      <ActivityFeed groups={groupByDay(page.items)} actors={actors} actor={actor} />
    </div>
  );
}
/**
 * Default content of the side panel slot.
 *
 * Owner D. Matches `/[orgSlug]`, so the overview page gets an activity rail
 * alongside it. The feed is a separate render tree from the main page, which is
 * the point of the parallel route: a slow activity query cannot hold up the
 * overview.
 *
 * The panel is `activity_feed`-gated; when the flag is off it renders nothing
 * and the aside collapses.
 */

import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { groupByDay, listActivity } from "@/server/services/activity-service";
import { loadTenantContext } from "../_lib/tenant-context";

type PageParams = { orgSlug: string };

export const dynamic = "force-dynamic";

const PANEL_ACTIVITY_LIMIT = 15;

export default async function Page(props: {
  params: Promise<PageParams>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // Next.js 16: params and searchParams are Promises and MUST be awaited.
  const { orgSlug } = await props.params;
  await props.searchParams;

  const { org, actor } = await loadTenantContext(orgSlug);

  if (!isEnabled("activity_feed", buildFlagContext(actor, org))) {
    return null;
  }
  if (!can(actor, "activity:read", { kind: "activity", orgId: org.id })) {
    return null;
  }

  const page = await listActivity(actor, {
    orgId: org.id,
    limit: PANEL_ACTIVITY_LIMIT,
  });
  const groups = groupByDay(page.items);

  return (
    <section className="p-6">
      <h2 className="text-sm font-semibold uppercase tracking-wide text-slate-500">
        Recent activity
      </h2>

      <div className="mt-4 space-y-6">
        {groups.map((group) => (
          <div key={group.day}>
            <p className="text-xs uppercase tracking-wide text-slate-400">
              {group.day}
            </p>
            <ul className="mt-2 space-y-2 text-sm text-slate-600">
              {group.events.map((event) => (
                <li key={event.id}>{event.summary}</li>
              ))}
            </ul>
          </div>
        ))}
      </div>
    </section>
  );
}
"use server";

/**
 * Updates org profile and settings.
 *
 * Owner D. `settings` is a partial patch — the service merges it over the
 * stored `OrganizationSettings` so a form that only touches `digestHourUtc`
 * cannot silently clear the flag overrides.
 *
 * Must call (do not reimplement): updateOrganizationSchema, can, getActor,
 * toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, orgTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import {
  updateOrganizationSchema,
  type UpdateOrganizationInput,
} from "@/schemas/organization";
import { updateOrganization } from "@/server/services/organization-service";
import type { ActionResult } from "@/types/api";
import type { Organization } from "@/types/organization";

const run = withAction<typeof updateOrganizationSchema, Organization>(
  updateOrganizationSchema,
  async (raw, actor) => {
    const input = raw as UpdateOrganizationInput;

    if (!can(actor, "org:update", { kind: "organization", orgId: input.orgId })) {
      throw new ForbiddenActionError("org:update");
    }

    const organization = await updateOrganization(actor, input);
    revalidateTagged([orgTag(input.orgId)], CACHE_PROFILES.minutes);
    return organization;
  },
  { revalidate: ["organization"], cacheProfile: "minutes" },
);

export async function updateOrganizationAction(
  raw: unknown,
): Promise<ActionResult<Organization>> {
  return run(raw);
}
"use client";

/**
 * Organization profile and settings editor.
 *
 * Owner D. Private to the settings route. `updateOrganizationSchema` accepts a
 * *partial* settings block, so the form only sends the keys it renders — the
 * service merges them over what is stored.
 */

import { useActionState } from "react";
import { updateOrganizationAction } from "@/actions/organizations/update-organization";
import { fieldErrorsFromZod } from "@/lib/errors";
import { updateOrganizationSchema } from "@/schemas/organization";
import type { ActionResult } from "@/types/api";
import type { Organization } from "@/types/organization";

export type OrganizationSettingsFormProps = {
  org: Organization;
  disabled: boolean;
};

type SettingsState = ActionResult<Organization> | null;

export function OrganizationSettingsForm(props: OrganizationSettingsFormProps) {
  const { org, disabled } = props;

  const [state, submit, pending] = useActionState<SettingsState, FormData>(
    async (_previous, formData) => {
      const logoUrl = String(formData.get("logoUrl") ?? "").trim();

      const parsed = updateOrganizationSchema.safeParse({
        orgId: org.id,
        name: String(formData.get("name") ?? ""),
        logoUrl: logoUrl.length === 0 ? null : logoUrl,
        settings: {
          allowPublicProjects: formData.get("allowPublicProjects") === "on",
          requireTwoFactor: formData.get("requireTwoFactor") === "on",
          digestHourUtc: Number(formData.get("digestHourUtc") ?? 7),
        },
      });

      if (!parsed.success) {
        return {
          ok: false,
          error: {
            code: "validation_failed",
            message: "Check the fields below.",
            fieldErrors: fieldErrorsFromZod(parsed.error),
          },
        };
      }

      return updateOrganizationAction(parsed.data);
    },
    null,
  );

  const fieldErrors = state?.ok === false ? (state.error.fieldErrors ?? {}) : {};

  return (
    <form action={submit} className="space-y-6">
      {state?.ok === true ? (
        <p className="rounded bg-emerald-50 px-3 py-2 text-sm text-emerald-700">
          Settings saved.
        </p>
      ) : null}
      {state?.ok === false && state.error.code === "forbidden" ? (
        <p role="alert" className="rounded bg-rose-50 px-3 py-2 text-sm text-rose-700">
          Your role does not allow changing organization settings.
        </p>
      ) : null}

      <div className="space-y-1">
        <label htmlFor="name" className="text-sm font-medium">
          Organization name
        </label>
        <input
          id="name"
          name="name"
          defaultValue={org.name}
          disabled={disabled}
          className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm disabled:bg-slate-100"
        />
        {fieldErrors.name !== undefined ? (
          <p className="text-xs text-rose-600">{fieldErrors.name[0]}</p>
        ) : null}
      </div>

      <div className="space-y-1">
        <label htmlFor="logoUrl" className="text-sm font-medium">
          Logo URL
        </label>
        <input
          id="logoUrl"
          name="logoUrl"
          type="url"
          defaultValue={org.logoUrl ?? ""}
          disabled={disabled}
          className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm disabled:bg-slate-100"
        />
      </div>

      <div className="space-y-1">
        <label htmlFor="digestHourUtc" className="text-sm font-medium">
          Digest hour (UTC)
        </label>
        <input
          id="digestHourUtc"
          name="digestHourUtc"
          type="number"
          min={0}
          max={23}
          defaultValue={org.settings.digestHourUtc}
          disabled={disabled}
          className="w-24 rounded-md border border-slate-300 px-3 py-2 text-sm disabled:bg-slate-100"
        />
        <p className="text-xs text-slate-500">
          The daily digest job runs once an hour and picks up organizations whose
          hour has come round.
        </p>
      </div>

      <label className="flex items-center gap-2 text-sm">
        <input
