s=s[:start]+'''/**
 * The window a digest covers, ending at the most recent local `digestHour:00`
 * at or before `reference` on the workspace clock — today's if it has passed,
 * yesterday's otherwise — so a job run early never mails an empty digest and
 * then skips the real one. It starts at the same local hour on the previous
 * calendar day, so across a DST change it spans 23 or 25 hours.
 */
export function digestWindow(
  digestHour: number,
  reference: Date,
  timeZone = "UTC",
): { start: IsoTimestamp; end: IsoTimestamp } {
  if (!Number.isInteger(digestHour) || digestHour < 0 || digestHour > 23) {
    throw new RangeError(`digestHour must be 0-23, got ${digestHour}`);
  }
  assertValidTimeZone(timeZone);

  const today = localDateOf(reference, timeZone);
  let endDate = today;
  let end = zonedWallTimeToUtc(today, digestHour, timeZone);
  if (end > reference.getTime()) {
    endDate = shiftCalendarDate(today, -1);
    end = zonedWallTimeToUtc(endDate, digestHour, timeZone);
  }
  const start = zonedWallTimeToUtc(
    shiftCalendarDate(endDate, -1),
    digestHour,
    timeZone,
  );

  return {
    start: toIsoTimestamp(new Date(start)),
    end: toIsoTimestamp(new Date(end)),
  };
}

/* ------------------------------------------------------------------------ */
/* Workspace clock                                                           */
/* ------------------------------------------------------------------------ */

const formatters = new Map<string, Intl.DateTimeFormat>();

function wallClockFormatter(timeZone: string): Intl.DateTimeFormat {
  let formatter = formatters.get(timeZone);
  if (formatter === undefined) {
    formatter = new Intl.DateTimeFormat("en-US", {
      timeZone,
      hourCycle: "h23",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
    });
    formatters.set(timeZone, formatter);
  }
  return formatter;
}

/** True when `Intl` recognises `timeZone` as a zone name. */
export function isValidTimeZone(timeZone: unknown): timeZone is string {
  if (typeof timeZone !== "string" || timeZone.trim().length === 0) return false;
  try {
    wallClockFormatter(timeZone);
    return true;
  } catch {
    return false;
  }
