python3 - <<'EOF'
p='src/server/repositories/organization-repository.ts'
s=open(p).read()
old='''  const settings = { ...current.settings, ...(patch.settings ?? {}) };
'''
new='''  // Keys sent as `undefined` keep their stored value.
  const settings = {
    ...current.settings,
    ...Object.fromEntries(
      Object.entries(patch.settings ?? {}).filter(([, value]) => value !== undefined),
    ),
  } as OrganizationSettings;
'''
assert old in s
s=s.replace(old,new)
s=s.replace('import type { Organization } from "@/types/organization";','import type { Organization, OrganizationSettings } from "@/types/organization";')
open(p,'w').write(s)
EOF
cat > tests/tmp-tz.test.ts <<'EOF'
import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("./server/_support/doubles/id"));
import * as orgRepo from "@/server/repositories/organization-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import { createTenant, issueInput, useTemporaryDatabase } from "./server/_support/fixtures";
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());
it("tz roundtrip", async () => {
  const t = await createTenant("tz-a");
  expect(t.org.settings.timeZone).toBe("UTC");
  const u = await orgRepo.updateOrg(t.org.id, { orgId: t.org.id, settings: { timeZone: "Asia/Tokyo" } });
  expect(u.settings.timeZone).toBe("Asia/Tokyo");
  await expect(orgRepo.updateOrg(t.org.id, { orgId: t.org.id, name: "zzz", settings: { timeZone: "Bad/Zone" } })).rejects.toBeInstanceOf(RangeError);
  const f = await orgRepo.findOrgById(t.org.id);
  expect(f?.settings.timeZone).toBe("Asia/Tokyo");
  expect(f?.name).not.toBe("zzz");
  const n = await issueRepo.nextIssueNumber(t.org.id, t.project.id);
  await issueRepo.insertIssue(issueInput(t.org.id, t.project.id, { dueAt: "2026-03-14T20:00:00.000Z" }), t.userIds.owner, n);
  const now = "2026-03-15T12:00:00.000Z" as never;
  expect((await issueRepo.listOverdueIssues(t.org.id, now)).length).toBe(0);
  expect((await issueRepo.listOverdueIssues(t.org.id, now, "UTC")).length).toBe(1);
  const stats = await projectRepo.getProjectStats(t.org.id, t.project.id, { now: new Date(now) });
  expect(stats.overdueIssues).toBe(0);
  const r = await runCleanupArchivedJob(new Date(now));
  expect(r.failed).toBe(0);
});
EOF
npx vitest run tests/tmp-tz.test.ts 2>&1 | grep -v "npm warn" | tail -15; rm tests/tmp-tz.test.ts; npx tsc --noEmit -p . 2>&1 | grep -v "npm warn" | head

